   <body>
     <div id="app"></div>
     <script>
       const Header = () => `
         <header class="site-header">
           <div class="brand" aria-label="Nova">
             <span class="brand-mark" aria-hidden="true">N</span>
             <span>Nova</span>
           </div>
           <p class="header-copy">Secure setup for your product workspace.</p>
         </header>
       `;

       const ConsentField = () => `
         <div class="form-field">
           <div class="checkbox-row">
             <input
               id="consent"
               name="consent"
               type="checkbox"
               required
               aria-describedby="consent-help"
             />
             <label for="consent">
               I agree to the terms of use <span class="required-marker" aria-hidden="true">*</span>
             </label>
           </div>
           <p id="consent-help" class="helper-text">
             Required to continue. <a href="#terms-of-use">Review the terms of use.</a>
           </p>
           <p id="consent-error" class="error-text" hidden>
             Error: Please agree to the terms of use before continuing.
           </p>
         </div>
       `;

       const ConsentForm = () => `
         <form id="consent-form" class="consent-form" novalidate>
           ${ConsentField()}
           <div class="actions">
             <button class="submit-button" type="submit">Continue</button>
           </div>
           <p id="form-status" class="status-message" aria-live="polite"></p>
         </form>
       `;

       const HeroCard = () => `
         <section class="panel" aria-labelledby="page-title">
           <p class="eyebrow">Quick setup</p>
           <h1 id="page-title">Confirm your product access</h1>
           <p class="intro">
             Before you finish setup, we need your consent to the terms that govern use of the workspace.
           </p>
           ${ConsentForm()}
         </section>
       `;

       const TermsCard = () => `
         <section id="terms-of-use" class="terms-card" aria-labelledby="terms-title">
           <h2 id="terms-title">Terms of use</h2>
           <p class="terms-copy">
             By continuing, you agree to use Nova responsibly, protect shared data, and follow your team's access policies.
           </p>
         </section>
       `;

       const App = () => `
         <a class="skip-link" href="#maincontent">Skip to main content</a>
         <div class="site-shell">
           ${Header()}
           <main id="maincontent" tabindex="-1">
             <div class="hero">
               ${HeroCard()}
               ${TermsCard()}
             </div>
           </main>
         </div>
       `;

       document.getElementById("app").innerHTML = App();

       const form = document.getElementById("consent-form");
       const consent = document.getElementById("consent");
       const helpTextId = "consent-help";
       const errorTextId = "consent-error";
       const errorText = document.getElementById(errorTextId);
       const statusMessage = document.getElementById("form-status");

       function setConsentValidity(isInvalid) {
         consent.setAttribute(
           "aria-describedby",
           isInvalid ? `${helpTextId} ${errorTextId}` : helpTextId
         );

         if (isInvalid) {
           consent.setAttribute("aria-invalid", "true");
           errorText.hidden = false;
           return;
         }

         consent.removeAttribute("aria-invalid");
         errorText.hidden = true;
       }

       consent.addEventListener("change", () => {
         if (consent.checked) {
           setConsentValidity(false);
         }

         statusMessage.textContent = "";
         statusMessage.classList.remove("is-success");
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();

         if (!consent.checked) {
           setConsentValidity(true);
           statusMessage.textContent = "";
           statusMessage.classList.remove("is-success");
           consent.focus();
           return;
         }

         setConsentValidity(false);
         statusMessage.textContent = "Thanks — your agreement has been recorded.";
         statusMessage.classList.add("is-success");
       });
     </script>
   </body>
 </html>

